"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[44397],{44397:function(e){e.exports=JSON.parse('{"content":"\\n<center>\\n<RestaurantCard\\n  cover=\\"/assets/snippets/location/56167f9423dce9aa9fe526e317aed5de.jpg\\"\\n  title=\\"AP House\\"\\n  cuisine=\\"Cafe\\"\\n  address=\\"AP House, 80, Commonwealth Street, Surry Hills, Sydney CBD, Sydney, New South Wales, 2010, Australia\\"\\n  rating=3.5\\n  tags=\\"cafe\\"\\n/>\\n</center>\\n\\n## Review\\nWe visited after hearing it was known as a great dessert spot.  \\n\\nThe system was to wait and get seated at a table, then order at the counter using that table number.  \\nNot knowing this, we went straight to the counter, figured it out on the spot, ordered with an empty table number, and quickly took that seat.  \\n\\nThe person taking our order was Korean here too, so we were able to order comfortably in Korean.  \\n\\nProbably because it was a weekday, many people seemed to be working or having external meetings.  \\nThere were also outdoor tables, and I thought if I lived here, it would be the perfect spot to work leisurely outside on a day off.  \\n## Pictures\\n<pictures>\\n<img src=\\"/assets/snippets/location/56167f9423dce9aa9fe526e317aed5de.jpg\\" style=\\"max-width: 100%; height: auto; object-fit: contain;\\" alt=\\"AP House\\">\\n<img src=\\"/assets/snippets/location/4c4b93a4230f18dec49fac3a9bcadc96.jpg\\" style=\\"max-width: 100%; height: auto; object-fit: contain;\\" alt=\\"AP House\\">\\n</pictures>\\n"}')}}]);